glsl3.vert:
precision lowp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1);
  gl_Position = pos;
  v_uv0 = a_uv0;
  v_color = a_color;
}

glsl3.frag:
precision lowp float;

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif

uniform PROPERTIES {
  float brightness;
  float blurAmount;
}

float rand(vec2 co) {

  return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

vec4 dim(vec4 col, float factor) {
  return vec4(col.rgb * factor, col.a);
}

vec4 blur(vec2 uv) {

  const float _repeats = 10.0;

  float _blurAmount = 0.08 * blurAmount;
  vec4 blurred = vec4(0.0);

  for (float i = 0.0; i < _repeats; i ++) {

    vec2 q = vec2(cos(degrees((i / _repeats) * 360.0)), sin(degrees((i / _repeats) * 360.0))) * (rand(vec2(i, uv.x + uv.y)) + _blurAmount);
    vec2 uv2 = uv + (q * _blurAmount);
    blurred += texture2D(texture, uv2).rgba / 2.0;

    q = vec2(cos(degrees((i / _repeats) * 360.0)), sin(degrees((i / _repeats) * 360.0))) * (rand(vec2(i + 2.0, uv.x + uv.y + 24.0)) + _blurAmount);
    uv2 = uv + (q * _blurAmount);
    blurred += texture2D(texture, uv2).rgba / 2.0;
  }

  blurred /= _repeats;
  return blurred;
}

void main () {
  vec4 o = vec4(dim(blur(v_uv0), brightness));
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

